/**
 * Grok Bot style mascot bodies: soft flat blobs with two slanted capsule eyes cut out of them.
 *
 * Captured data, do not hand-edit. The outlines and eyes are the settled idle pose of each body as drawn
 * by Grok Bot's own mark renderer (its compact sidebar size), sampled headlessly and mapped into the
 * mascot face box at Grok's proportion: the body spans 0.92 of the nominal avatar size. Eyes are
 * resampled to 48-point rings in face-box units so the shared face engine can blink, look and morph them.
 */

/** Every Grok-style body id, in the order the picker shows them. */
export const GROK_BODY_IDS = ["blob", "tablet", "cloud", "flower", "sparkle", "wedge", "heart", "fruit", "squircle", "clover", "star", "square", "teardrop", "pebble", "bean", "egg", "capsule", "cylinder", "hex", "gem", "crystal", "shield", "dome", "arch", "leaf", "house"] as const;

export type GrokBodyId = (typeof GROK_BODY_IDS)[number];

export interface GrokBody {
  id: GrokBodyId;
  name: string;
  /** Maps the 192-unit outline into the face box. */
  fit: string;
  /** Body markup. `{{GRADIENT}}` is replaced with the bot's own paint. */
  body: string;
  /** The outline alone, used as the face clip. */
  clip: string;
  /** Identity: the eyes below are already in face-box units. */
  anchor: { x: number; y: number; scale: number };
  /** The two eyes, left first, 48 points each, in face-box units. */
  face: { eyes: [number, number][][] };
}

const FIT = "translate(-83.9443 -83.9443) scale(2.064737)";
const ANCHOR = { x: 120, y: 122.5, scale: 1 };

const ring = (encoded: string): [number, number][] => {
  const n = encoded.split(" ").map(Number);
  const out: [number, number][] = [];
  for (let i = 0; i + 1 < n.length; i += 2) out.push([n[i]!, n[i + 1]!]);
  return out;
};

function body(id: GrokBodyId, name: string, d: string, eyes: [string, string], painted: [string, string][] = []): GrokBody {
  const extra = painted.map(([path, fill]) => `<path fill="${fill}" d="${path}"/>`).join("");
  return { id, name, fit: FIT, body: `<path fill="{{GRADIENT}}" d="${d}"/>${extra}`, clip: `<path d="${d}"/>`, anchor: ANCHOR, face: { eyes: eyes.map(ring) } };
}

